/* 알림 수신자 정보 조회(이메일·닉네임) */
SELECT MBR_SN
     , ACNT_EML_ENC
     , MBR_NCNM
  FROM MBR
 WHERE MBR_SN = #{mbrSn}

mapper.update:
/* 알림 수신 설정 저장 */
UPDATE MBR
   SET EML_NOTI_RCPTN_YN = #{setting.emlNotiRcptnYn}
     , INAPP_NOTI_RCPTN_YN = #{setting.inappNotiRcptnYn}
     , CARE_SCHDL_NOTI_RCPTN_YN = #{setting.careSchdlNotiRcptnYn}
     , THDY_BFHD_NOTI_YN = #{setting.thdyBfhdNotiYn}
     , D1_BFHD_NOTI_YN = #{setting.d1BfhdNotiYn}
     , D3_BFHD_NOTI_YN = #{setting.d3BfhdNotiYn}
     , D7_BFHD_NOTI_YN = #{setting.d7BfhdNotiYn}
     , MTCH_DLNG_NOTI_RCPTN_YN = #{setting.mtchDlngNotiRcptnYn}
     , CMNT_NOTI_RCPTN_YN = #{setting.cmntNotiRcptnYn}
     , LOST_EXPRY_NOTI_RCPTN_YN = #{setting.lostExpryNotiRcptnYn}
     , EXPND_LIM_NOTI_RCPTN_YN = #{setting.expndLimNotiRcptnYn}
     , MDFR_ID = #{actorId}
     , MDFCN_DT = NOW()
 WHERE MBR_SN = #{setting.mbrSn}

mapper.select:
/* 안 읽은 알림 수 조회 */
SELECT COUNT(*)
  FROM INAPP_NOTI
 WHERE MBR_SN = #{mbrSn}
   AND PRSL_DT IS NULL
   AND AUTO_HIDE_DT > NOW()

/* 알림 드롭다운 목록 조회 */ SELECT INAPP_NOTI_SN , NOTI_TYPE_CD , NOTI_TTL , NOTI_CN , MVMN_PATH , PRSL_DT , REG_DT FROM INAPP_NOTI WHERE MBR_SN = #{mbrSn} AND AUTO_HIDE_DT > NOW()
AND NOTI_TYPE_CD IN
#{notiTypeCd}
ORDER BY (PRSL_DT IS NULL) DESC , REG_DT DESC , INAPP_NOTI_SN DESC LIMIT #{limit}

/* 본인 알림 존재 여부 */
SELECT EXISTS (
       SELECT 1
         FROM INAPP_NOTI
        WHERE INAPP_NOTI_SN = #{inappNotiSn}
          AND MBR_SN = #{mbrSn}
       )

mapper.update:
/* 알림 읽음 처리 */
UPDATE INAPP_NOTI
   SET PRSL_DT = NOW()
     , MDFCN_DT = NOW()
 WHERE INAPP_NOTI_SN = #{inappNotiSn}
   AND MBR_SN = #{mbrSn}
   AND PRSL_DT IS NULL
